import sys
from collections import OrderedDict

def main():
    lines = sys.stdin.read().splitlines()
    capacity = int(lines[0])
    cache = OrderedDict()
    for line in lines[1:]:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "put":
            key = parts[1]
            value = parts[2]
            if len(cache) >= capacity:
                oldest_key = next(iter(cache))
                del cache[oldest_key]
                print("evict", oldest_key)
            cache[key] = value
        elif parts[0] == "get":
            value = cache.get(key, "miss")
            print(value)
        elif parts[0] == "dump":
            if not cache:
                print("empty")
            else:
                print(" ".join(cache.keys()))


if __name__ == "__main__":
    main()
